create table FM_DATE (COMPANY VARCHAR(20) not null  ,SYSTEM_PHASE VARCHAR(3) null  ,ACCT_EOD_FLAG VARCHAR(1) null  ,SUSPEND_FLAG VARCHAR(1) null  ,LAST_RUN_DATE TIMESTAMP(3) null  ,RUN_DATE TIMESTAMP(3) null  ,NEXT_RUN_DATE TIMESTAMP(3) null  ,MTH_END_DATE TIMESTAMP(3) null  ,QUR_END_DATE TIMESTAMP(3) null  ,HALF_END_DATE TIMESTAMP(3) null  ,YR_END_DATE TIMESTAMP(3) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(COMPANY));